// INDIE PORT v0.19 — explicit social sharing + safe public-client adapter states
let V19_PUBLIC_CONFIG={googleClientId:"",kakaoJsKey:"",naverClientId:"",canonicalUrl:""};

function v19ConfigValue(name){return String((V19_PUBLIC_CONFIG&&V19_PUBLIC_CONFIG[name])||"").trim()}
function v19CanonicalUrl(){return v19ConfigValue("canonicalUrl")||location.href.split("#")[0]}
function v19LatestReview(code){
  try{const list=typeof reviews==="function"?reviews().filter(x=>x.code===code):[];return list.length?list[list.length-1]:null}
  catch(_){return null}
}
function v19SharePayload(code){
  const all=typeof MOVIES!=="undefined"?MOVIES:{},m=all[code]||{},review=v19LatestReview(code)||{},rating=Number(review.rating||0),tags=Array.isArray(review.tags)?review.tags.filter(Boolean):[];
  const parts=[m.title||"INDIE PORT",review.text||review.body||"",rating?"★ "+rating.toFixed(1):"",tags.length?tags.map(x=>String(x).startsWith("#")?x:"#"+x).join(" "):""].filter(Boolean);
  return {title:m.title||"INDIE PORT",text:parts.join("\n"),url:v19CanonicalUrl()};
}
function v19OpenPopup(url){const w=window.open(url,"_blank","noopener,noreferrer,width=760,height=680");if(!w)toast("팝업이 차단되었습니다. 브라우저 설정을 확인해주세요.")}
async function v19CopyShare(code){
  const p=v19SharePayload(code),text=[p.text,p.url].filter(Boolean).join("\n");
  try{
    if(navigator.clipboard&&navigator.clipboard.writeText)await navigator.clipboard.writeText(text);
    else{const ta=document.createElement("textarea");ta.value=text;ta.style.position="fixed";ta.style.opacity="0";document.body.appendChild(ta);ta.select();document.execCommand("copy");ta.remove()}
    toast("공유 문구와 링크를 복사했습니다.");
  }catch(e){console.warn("copy share",e);toast("링크 복사에 실패했습니다.")}
}
async function v19SystemShare(code){
  const p=v19SharePayload(code);if(!navigator.share)return v19CopyShare(code);
  try{await navigator.share(p)}catch(e){if(e&&e.name!=="AbortError"){console.warn("system share",e);toast("공유를 열지 못했습니다.")}}
}
function v19ShareX(code){const p=v19SharePayload(code);v19OpenPopup("https://twitter.com/intent/tweet?"+new URLSearchParams({text:p.text,url:p.url}))}
function v19ShareFacebook(code){const p=v19SharePayload(code);v19OpenPopup("https://www.facebook.com/sharer/sharer.php?"+new URLSearchParams({u:p.url,quote:p.text}))}
async function v19ShareKakao(code){
  const p=v19SharePayload(code),key=v19ConfigValue("kakaoJsKey");
  if(key&&window.Kakao&&window.Kakao.Share&&window.Kakao.Share.sendDefault){
    try{
      if(window.Kakao.isInitialized&&!window.Kakao.isInitialized())window.Kakao.init(key);
      const all=typeof MOVIES!=="undefined"?MOVIES:{},poster=(all[code]||{}).poster||location.origin+"/icons/icon-512.png";
      window.Kakao.Share.sendDefault({objectType:"feed",content:{title:p.title,description:p.text.slice(0,180),imageUrl:new URL(poster,location.href).href,link:{mobileWebUrl:p.url,webUrl:p.url}},buttons:[{title:"INDIE PORT에서 보기",link:{mobileWebUrl:p.url,webUrl:p.url}}]});
      return;
    }catch(e){console.warn("kakao share",e)}
  }
  if(navigator.share){toast("공유 시트에서 카카오톡을 선택해주세요.");return v19SystemShare(code)}
  toast(key?"카카오 SDK 연결을 확인해주세요.":"카카오는 시스템 공유 또는 KAKAO_JS_KEY 설정 후 사용할 수 있습니다.");
  return v19CopyShare(code);
}
function v19ShareAction(action,code){
  if(!code)return toast("공유할 영화를 먼저 선택해주세요.");
  if(action==="system")return v19SystemShare(code);
  if(action==="copy")return v19CopyShare(code);
  if(action==="x")return v19ShareX(code);
  if(action==="facebook")return v19ShareFacebook(code);
  if(action==="kakao")return v19ShareKakao(code);
}
function v19InjectShareActions(panel,code){
  const sheet=panel&&panel.querySelector(".share-sheet");if(!sheet)return;
  let box=sheet.querySelector(".v19-social-actions");
  if(!box){
    box=document.createElement("section");box.className="v19-social-actions";
    box.innerHTML='<div class="v19-social-head"><b>바로 공유</b><small>이미지 파일 공유는 기존 SNS 공유 버튼을 사용하세요.</small></div><div class="v19-social-grid"><button data-v19-share="system">시스템 공유</button><button data-v19-share="copy">링크 복사</button><button data-v19-share="x">X</button><button data-v19-share="facebook">Facebook</button><button data-v19-share="kakao">Kakao</button></div>';
    (sheet.querySelector(".share-actions")||sheet.querySelector(".share-preview")||sheet).insertAdjacentElement("afterend",box);
    box.querySelectorAll("[data-v19-share]").forEach(btn=>btn.onclick=()=>v19ShareAction(btn.dataset.v19Share,activeMovieCode));
  }
  box.dataset.code=code||activeMovieCode||"";
}
function v19WrapShareOpeners(){
  if(typeof window.openSharePanelV05==="function"&&!window.openSharePanelV05.__v19){
    const base=window.openSharePanelV05,wrapped=function(){const args=[...arguments],out=base.apply(this,args);setTimeout(()=>v19InjectShareActions(document.getElementById("sharePanelV05"),args[0]),0);return out};wrapped.__v19=true;window.openSharePanelV05=wrapped;
  }
  if(typeof window.openSharePanel==="function"&&!window.openSharePanel.__v19){
    const base=window.openSharePanel,wrapped=function(){const args=[...arguments],out=base.apply(this,args);setTimeout(()=>v19InjectShareActions(document.getElementById("sharePanel"),args[0]),0);return out};wrapped.__v19=true;window.openSharePanel=wrapped;
  }
}
function v19ProviderState(provider){
  const key=provider==="google"?v19ConfigValue("googleClientId"):provider==="kakao"?v19ConfigValue("kakaoJsKey"):v19ConfigValue("naverClientId"),p=typeof profile==="function"?profile():{};
  if(p&&p.provider===provider&&p.connected===true)return {label:"연결됨",state:"connected"};
  return key?{label:"연결 가능",state:"ready"}:{label:"설정 필요",state:"needs-config"};
}
function v19AuthAction(provider){
  const state=v19ProviderState(provider);
  if(state.state==="needs-config"){const name=provider==="google"?"GOOGLE_CLIENT_ID":provider==="kakao"?"KAKAO_JS_KEY":"NAVER_CLIENT_ID";toast(name+" 설정이 필요합니다.");return}
  toast("공개 클라이언트 설정을 확인했습니다. 클라우드 동기화 서버 연결 전까지 기기 프로필 모드로 유지합니다.");
}
function v19EnhanceAccountPanel(){
  const panel=document.getElementById("accountPanel");if(!panel)return false;
  const p=panel.querySelector("p");if(p)p.textContent="기록은 기본적으로 이 기기에 저장됩니다. 공개 클라이언트 설정이 있는 공급자만 연결 가능 상태로 표시하며, 서버 검증이 필요한 OAuth는 연결된 척하지 않습니다.";
  panel.querySelectorAll("[data-social]").forEach(btn=>{const provider=btn.dataset.social,state=v19ProviderState(provider),name=provider==="google"?"Google":provider==="kakao"?"Kakao":"Naver";btn.textContent=name+" · "+state.label;btn.dataset.state=state.state;btn.onclick=()=>v19AuthAction(provider)});
  const auth=document.getElementById("authState");if(auth)auth.textContent="기기 프로필 모드 · 공개 설정은 data/public-config.json";
  return true;
}
async function v19LoadPublicConfig(){try{const res=await fetch("./data/public-config.json?v="+Date.now(),{cache:"no-store"});if(res.ok)V19_PUBLIC_CONFIG=Object.assign({},V19_PUBLIC_CONFIG,await res.json())}catch(e){console.warn("public config",e)}}
(function initV19(){v19LoadPublicConfig().finally(()=>{v19WrapShareOpeners();let n=0;const timer=setInterval(()=>{n++;v19WrapShareOpeners();if(v19EnhanceAccountPanel()||n>80)clearInterval(timer)},125)})})();

