import json, os, re, unicodedata
from datetime import datetime, timezone
from pathlib import Path
from urllib.parse import urlencode, quote
from urllib.request import Request, urlopen

ROOT=Path(__file__).resolve().parents[1]
MOVIES_PATH=ROOT/'data'/'movies.json'
STATUS_PATH=ROOT/'data'/'api-status.json'
UA='INDIE+POHANG/0.19 (non-commercial cinema discovery app)'
CACHE={}

def now():
    return datetime.now(timezone.utc).isoformat()

def safe_error(exc):
    return type(exc).__name__

def get_json(url, headers=None, timeout=12, retries=1):
    h={'User-Agent':UA,'Accept':'application/json'}
    if headers:h.update(headers)
    last=None
    for _ in range(retries+1):
        try:
            with urlopen(Request(url,headers=h),timeout=timeout) as r:
                return json.loads(r.read().decode('utf-8','replace'))
        except Exception as exc:
            last=exc
    raise last

def norm(value):
    value=unicodedata.normalize('NFKC',str(value or '')).lower()
    return re.sub(r'[^0-9a-z가-힣]+','',value)

def year_hint(movie):
    for raw in [movie.get('year'),movie.get('releaseDate'),*(movie.get('meta') or [])]:
        m=re.search(r'(19|20)\d{2}',str(raw or ''))
        if m:return m.group(0)
    return ''

def set_if_blank(obj,key,value,source):
    if value and not obj.get(key):
        obj[key]=value
        obj.setdefault('enrichedBy',{})[key]=source

def status_entry(configured,healthy,error=None,**extra):
    return {'configured':bool(configured),'healthy':bool(healthy),'lastCheck':now(),'lastError':error,**extra}

pack=json.loads(MOVIES_PATH.read_text(encoding='utf-8'))
movies=pack.get('movies',{})
try: status=json.loads(STATUS_PATH.read_text(encoding='utf-8')) if STATUS_PATH.exists() else {}
except Exception: status={}
kobis=os.getenv('KOBIS_KEY','').strip()
kmdb=os.getenv('KMDB_KEY','').strip()
tmdb=os.getenv('TMDB_TOKEN','').strip() or os.getenv('TMDB_KEY','').strip()

def wikimedia_person(name):
    if not name:return None
    key=('wm',name)
    if key in CACHE:return CACHE[key]
    try:
        search=get_json('https://ko.wikipedia.org/w/api.php?'+urlencode({'action':'query','list':'search','srsearch':name+' 영화 감독','srlimit':6,'format':'json','utf8':1}))
        best=None;best_score=-1
        n=norm(name);tokens=[norm(x) for x in re.split(r'\s+',name) if norm(x)]
        for hit in search.get('query',{}).get('search',[]):
            title=hit.get('title','')
            summary=get_json('https://ko.wikipedia.org/api/rest_v1/page/summary/'+quote(title))
            desc=str(summary.get('description',''))
            extract=str(summary.get('extract',''))
            page_type=str(summary.get('type',''))
            blob=(desc+' '+extract).lower()
            if page_type=='disambiguation' or '동음이의' in blob or 'disambiguation' in blob:continue
            t=norm(summary.get('title',title))
            score=0
            if t==n:score+=8
            elif n and n in t:score+=5
            elif tokens and all(x in t for x in tokens):score+=4
            if any(x in blob for x in ('영화 감독','영화감독','감독','filmmaker','film director','screenwriter','producer')):score+=3
            if score>best_score:
                best_score=score
                best={'title':summary.get('title',title),'description':desc,'extract':extract,'url':summary.get('content_urls',{}).get('desktop',{}).get('page',''),'confidence':score}
        CACHE[key]=best if best_score>=7 else None
        return CACHE[key]
    except Exception:
        CACHE[key]=None
        return None

def kobis_movie(title,movie):
    if not kobis:return None
    try:
        data=get_json('https://kobis.or.kr/kobisopenapi/webservice/rest/movie/searchMovieList.json?'+urlencode({'key':kobis,'movieNm':title,'itemPerPage':20}))
        rows=data.get('movieListResult',{}).get('movieList',[])
        wanted=norm(title);year=year_hint(movie);director=norm(str(movie.get('director','')).split('|')[0])
        scored=[]
        for row in rows:
            score=0
            if norm(row.get('movieNm'))==wanted:score+=6
            if year and str(row.get('prdtYear',''))==year:score+=3
            dirs=' '.join(x.get('peopleNm','') for x in row.get('directors',[]) if isinstance(x,dict))
            if director and director in norm(dirs):score+=3
            scored.append((score,row))
        scored.sort(key=lambda x:x[0],reverse=True)
        if not scored or scored[0][0]<6:return None
        row=scored[0][1];code=row.get('movieCd')
        detail=get_json('https://kobis.or.kr/kobisopenapi/webservice/rest/movie/searchMovieInfo.json?'+urlencode({'key':kobis,'movieCd':code})).get('movieInfoResult',{}).get('movieInfo',{}) if code else {}
        return {'movieCd':code,'movieNm':detail.get('movieNm') or row.get('movieNm'),'prdtYear':detail.get('prdtYear') or row.get('prdtYear'),'nations':[x.get('nationNm') for x in detail.get('nations',[]) if x.get('nationNm')],'genres':[x.get('genreNm') for x in detail.get('genres',[]) if x.get('genreNm')],'directors':[x.get('peopleNm') for x in detail.get('directors',[]) if x.get('peopleNm')],'actors':[x.get('peopleNm') for x in detail.get('actors',[])[:10] if x.get('peopleNm')]}
    except Exception:return None

def kmdb_movie(title,movie):
    if not kmdb:return None
    try:
        data=get_json('https://api.koreafilm.or.kr/openapi-data2/wisenut/search_api/search_json2.jsp?'+urlencode({'collection':'kmdb_new2','detail':'Y','title':title,'ServiceKey':kmdb}))
        rows=[]
        for block in data.get('Data',[]) or []:rows.extend(block.get('Result',[]) or [])
        if not rows:return None
        wanted=norm(title);rows.sort(key=lambda x:0 if wanted and wanted in norm(x.get('title')) else 1)
        row=rows[0]
        return {'DOCID':row.get('DOCID'),'title':re.sub(r'!HS|!HE','',str(row.get('title',''))).strip(),'titleEng':row.get('titleEng'),'prodYear':row.get('prodYear'),'genre':row.get('genre'),'posters':row.get('posters'),'stlls':row.get('stlls')}
    except Exception:return None

def tmdb_movie(title,movie):
    if not tmdb:return None
    try:
        headers={};params={'query':title,'language':'ko-KR','include_adult':'false'}
        y=year_hint(movie)
        if y:params['primary_release_year']=y
        if len(tmdb)>60:headers['Authorization']='Bearer '+tmdb
        else:params['api_key']=tmdb
        found=get_json('https://api.themoviedb.org/3/search/movie?'+urlencode(params),headers)
        rows=found.get('results') or [];wanted=norm(title)
        rows.sort(key=lambda x:(0 if norm(x.get('title'))==wanted or norm(x.get('original_title'))==wanted else 1,-float(x.get('popularity') or 0)))
        row=rows[0] if rows else None
        if not row:return None
        mid=row.get('id');p={'language':'ko-KR','append_to_response':'credits,recommendations'}
        if len(tmdb)<=60:p['api_key']=tmdb
        d=get_json(f'https://api.themoviedb.org/3/movie/{mid}?'+urlencode(p),headers)
        return {'id':d.get('id'),'title':d.get('title'),'original_title':d.get('original_title'),'release_date':d.get('release_date'),'vote_average':d.get('vote_average'),'production_countries':[x.get('name') for x in d.get('production_countries',[]) if x.get('name')],'genres':[x.get('name') for x in d.get('genres',[]) if x.get('name')],'cast':[x.get('name') for x in d.get('credits',{}).get('cast',[])[:8] if x.get('name')],'directors':[x.get('name') for x in d.get('credits',{}).get('crew',[]) if x.get('job')=='Director' and x.get('name')],'recommendations':[{'id':x.get('id'),'title':x.get('title'),'poster_path':x.get('poster_path')} for x in d.get('recommendations',{}).get('results',[])[:5]]}
    except Exception:return None

wm_ok=False
for code,m in movies.items():
    ext=m.setdefault('external',{})
    director=str(m.get('director','')).split('|')[0].strip()
    if director:
        wm=wikimedia_person(director)
        if wm:ext['wikimedia']=wm;wm_ok=True
        else:ext.pop('wikimedia',None)
    if kobis:
        d=kobis_movie(m.get('title',''),m)
        if d:
            ext['kobis']=d;m['kobisCode']=d.get('movieCd') or m.get('kobisCode')
            set_if_blank(m,'country',', '.join(d.get('nations',[])),'kobis')
            set_if_blank(m,'genre',', '.join(d.get('genres',[])),'kobis')
    if kmdb:
        d=kmdb_movie(m.get('title',''),m)
        if d:ext['kmdb']=d
    if tmdb:
        d=tmdb_movie(m.get('title',''),m)
        if d:
            ext['tmdb']=d;m['tmdbId']=d.get('id') or m.get('tmdbId');m['tmdbVoteAverage']=d.get('vote_average')
            set_if_blank(m,'country',', '.join(d.get('production_countries',[])),'tmdb')
            set_if_blank(m,'genre',', '.join(d.get('genres',[])),'tmdb')

status['wikimedia']=status_entry(True,wm_ok,None if wm_ok else 'NO_CONFIDENT_MATCH')
status['kobis']=status_entry(bool(kobis),bool(kobis) and any('kobis' in (m.get('external') or {}) for m in movies.values()),None if kobis else 'CONFIG_REQUIRED')
status['kmdb']=status_entry(bool(kmdb),bool(kmdb) and any('kmdb' in (m.get('external') or {}) for m in movies.values()),None if kmdb else 'CONFIG_REQUIRED')
status['tmdb']=status_entry(bool(tmdb),bool(tmdb) and any('tmdb' in (m.get('external') or {}) for m in movies.values()),None if tmdb else 'CONFIG_REQUIRED')
pack['movies']=movies
MOVIES_PATH.write_text(json.dumps(pack,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
STATUS_PATH.write_text(json.dumps(status,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'providerStatusUpdated':True,'movies':len(movies)},ensure_ascii=True))

import json, os
from pathlib import Path
from urllib.request import Request, urlopen

ROOT=Path(__file__).resolve().parents[1]
MOVIES=json.loads((ROOT/'data'/'movies.json').read_text(encoding='utf-8')).get('movies',{})
MANIFEST=ROOT/'data'/'share-assets.json'
OUT=ROOT/'assets'/'share'
OUT.mkdir(parents=True,exist_ok=True)
UA={'User-Agent':'Mozilla/5.0 INDIE+POHANG/0.19'}
try: previous=json.loads(MANIFEST.read_text(encoding='utf-8')) if MANIFEST.exists() else {}
except Exception: previous={}

def fetch(url,path):
    if not url:return False
    tmp=path.with_name(path.name+'.tmp')
    try:
        with urlopen(Request(url,headers=UA),timeout=30) as r:tmp.write_bytes(r.read())
        if tmp.stat().st_size<=0:raise ValueError('empty asset')
        os.replace(tmp,path);return True
    finally:
        tmp.unlink(missing_ok=True)

def save_asset(code,label,url):
    if not url:return None
    ext='.png' if '.png' in url.lower() else '.jpg'
    path=OUT/f'{code}-{label}{ext}'
    if path.exists() and path.stat().st_size>0:return f'./assets/share/{path.name}'
    try:
        fetch(url,path);return f'./assets/share/{path.name}'
    except Exception as exc:
        print(f'{code} {label} skipped: {type(exc).__name__}');return None

manifest={}
for code,m in MOVIES.items():
    old=previous.get(code,{}) if isinstance(previous.get(code),dict) else {}
    entry={k:v for k,v in old.items() if k in ('poster','still','stills')}
    poster=save_asset(code,'poster',m.get('poster') or '')
    if poster:entry['poster']=poster
    stills=[];sources=m.get('stills') or ([m.get('still')] if m.get('still') else [])
    for i,url in enumerate(sources[:4],1):
        local=save_asset(code,f'still{i}',url)
        if local:stills.append(local)
        elif i-1<len(old.get('stills',[])):stills.append(old['stills'][i-1])
    if stills:entry['stills']=stills;entry['still']=stills[0]
    manifest[code]=entry
tmp=MANIFEST.with_name(MANIFEST.name+'.tmp')
tmp.write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');os.replace(tmp,MANIFEST)
print(json.dumps({'cachedMovies':len(manifest),'stills':sum(len(v.get('stills',[])) for v in manifest.values())}))

{
  "priority": ["dtryx", "kmdb", "kobis", "tmdb", "wikimedia", "googleNewsRss"],
  "providers": {
    "dtryx": {"enabled": true, "keyRequired": false, "roles": ["schedule","poster","synopsis","cast","director","stills","trailer"]},
